import{_ as r}from"./chunks/25d4230f38b31b3c495f.Bt2AXpTK.js";import{_ as l,C as a,o,c as i,j as p,a as n,E as s,a5 as g}from"./chunks/framework.DNkHA0lr.js";const _=JSON.parse('{"title":"如果你想在未来10年蓬勃发展，请学习这项技能","description":"","frontmatter":{"title":"如果你想在未来10年蓬勃发展，请学习这项技能","originalTitle":"Learn This Skill If You Want To Thrive The Next 10 Years","date":"2024-01-19","originalUrl":"https://thedankoe.com/letters/learn-this-skill-if-you-want-to-survive-the-next-10-years/","minutes":17,"sourceHash":"68f11fad00f7a59cd69862d74abdde8ece51e527c6bfbcf81bc4075ba8a91be9","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/learn-this-skill-if-you-want-to-survive-the-next-10-years/"}]]},"headers":[],"relativePath":"letters/learn-this-skill-if-you-want-to-survive-the-next-10-years.md","filePath":"letters/learn-this-skill-if-you-want-to-survive-the-next-10-years.md"}'),h={name:"letters/learn-this-skill-if-you-want-to-survive-the-next-10-years.md"};function c(u,e,d,m,f,b){const t=a("ArticleMeta");return o(),i("div",null,[e[0]||(e[0]=p("h1",{id:"如果你想在未来10年蓬勃发展-请学习这项技能",tabindex:"-1"},[n("如果你想在未来10年蓬勃发展，请学习这项技能 "),p("a",{class:"header-anchor",href:"#如果你想在未来10年蓬勃发展-请学习这项技能","aria-label":'Permalink to "如果你想在未来10年蓬勃发展，请学习这项技能"'},"​")],-1)),s(t),e[1]||(e[1]=g('<p><a href="https://www.youtube.com/embed/_VLZ4b9LHLs?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>从我记事起，我的目标就是以自己热爱的事情谋生。这难道不是每个人都想要的吗？</p><p>我的家人、老师，甚至我在网上关注的人，都对我大喊大叫，让我走别的路。</p><p>所以我就照做了。</p><ul><li>上了大学（读了5年也没毕业）</li><li>业余时间学习创意技能</li><li>尝试了所有能想到的在线生意</li><li>学习编程，因为听说它“很赚钱”</li><li>从大学退学，因为它在浪费我的时间</li><li>在一家设计公司找了一份年薪5.5万美元的初级网页开发工作</li></ul><p>在整个旅程中，“做我热爱的事情”的梦想一直萦绕在我的脑海深处。我不断地被它提醒。从16岁到25岁，没有哪一刻我不在做一个有意义的副业项目。</p><p>直到今天我依然保持着这个习惯。如果不是商业项目，那就是健康项目。</p><p>这就是我走出低谷的方式，因为我陷入低谷的唯一原因就是精神熵（psychic entropy），即大脑趋向于无序。这意味着我没有一个能让我集中注意力的目标、项目或优先事项。</p><p>我目前的项目有Kortex（第二大脑软件）、Kortex University（一所面向创作者的学校）、推广我的书、策划另一本书（准备在Kortex里写），以及在天气变暖开始减脂前再长几磅肉。</p><p>为什么我要告诉你这些？</p><p>因为我意识到，大多数人根本不知道自己在说什么。</p><p>我当时在听取那些并未实现我想实现的目标的人给出的职业和人生建议。在他们封闭的思想里，我想要创造的现实是不可能的，但我为了保持理智，却不断地重新投入到我喜欢做的项目中去。</p><p>大多数人都没有一个能创造他们想要的未来的个人项目。</p><p>大多数人没有意识到，要<em>创造**他们</em>想要的未来，个人项目并不是可有可无的。</p><p>唯一的另一个选择就是按照你被设定的程序去生活，追求社会为你设定的目标，并为实现这些目标的项目而工作。如果你不花1小时来构建自己的梦想，你就会一辈子每天花8小时去构建别人的梦想。</p><p>10年前，我的心态是：<em>“如果我能把这些热爱项目中的任何一个变现，我就稳了。我需要做的就是不断学习和构建，直到有一个成功。我需要通过获取技能和经验来提高我碰上好运的能力。这可能需要10年，但有些人上学还上了12年呢。就算我失败了，我的处境也跟原来差不多。”</em></p><p>在对人们告诉你去学的每一项“有市场价值的技能”进行了多年的试错之后，我发现了这个秘密。</p><p>额，其实也不算什么秘密，但我得让你产生好奇心继续往下读嘛，你懂的。</p><p>在我们开始之前：</p><p>这篇文章会很长。请确保你有足够的精力和时间来阅读它。我保证它绝对值得。</p><p>如果你想学习写作的来龙去脉（一篇文章是讲不完的），去看看<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2小时作家（2-Hour Writer）。</a></p><h2 id="为什么是写作" tabindex="-1">为什么是写作？ <a class="header-anchor" href="#为什么是写作" aria-label="Permalink to &quot;为什么是写作？&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><p>媒体的未来是去中心化的。</p><p>人们现在并且将继续转向：</p><ul><li>通过社交媒体获取新闻</li><li>通过课程获取教育</li><li>通过创作者获取知识</li></ul><p>我不想听什么AI正在颠覆写作这种话。</p><p>我认为我们在网上消费的唯一内容是由一个没有灵魂的机器人创造的，这根本不可能。</p><p>AI的出现似乎对人类的创造力更加有利，而媒体就是前端创造力的载体。</p><p>AI是让作家变得更加高产的工具。</p><p>写作是一项能为你学到的任何其他技能注入生命力的技能。</p><p>它是<em>最核心的</em>元技能，人们总是逃避学习它，直到被逼无奈（因为需要生存）。</p><p>他们看不到它的重要性，因为它<em>“只不过是普普通通的写作罢了，谁需要学那个啊？”</em></p><p>我尝试过的几乎每一个商业模式都失败了，这是有原因的。</p><p>数字艺术、SEO、Facebook广告、一件代发、电商商店等等。</p><p>我太过于专注于学习技能和建网站了，以至于忘了其实我迟早得去获取客户。</p><p>你如何获取客户？</p><p>写作。</p><p>内容（或媒体）是互联网的前端。在充满自嘲梗和无价值内容的汪洋大海中，这就是你捕捉、维持和转化注意力的方式。</p><p>内容的基础就是写作。</p><ul><li><strong>发推？</strong> 写作。</li><li><strong>发长推（Threads）？</strong> 写作。</li><li><strong>时事通讯（Newsletters）？</strong> 写作。</li><li><strong>博客文章？</strong> 写作。</li><li><strong>冷邮件（Cold emails）？</strong> 写作。</li><li><strong>社交媒体配文？</strong> 写作。</li><li><strong>着陆页（Landing pages）？</strong> 写作。</li><li><strong>产品描述？</strong> 写作。</li><li><strong>课程模块？</strong> 写作。</li><li><strong>客户沟通？</strong> 写作。</li><li><strong>客户资源？</strong> 写作。</li><li><strong>任何形式的广告？</strong> 从写作开始。</li><li><strong>YouTube视频？</strong> 有了写好的脚本才能做到最好。</li><li><strong>Instagram Reels和TikToks短视频？</strong> 就像读写得好的推文。</li><li><strong>Instagram上的图片？</strong> 通常是根据一段写得很好的名言或语录设计的。</li><li><strong>任何其他形式的在线营销、广告或娱乐？</strong> 都始于写作。</li></ul><p><em>你的受众、客户和人脉网络看到的一切，都始于写作。</em></p><p>不要低估那种力量。</p><p>每一个做生意的人，骨子里都是一个作家，他们只是没给自己贴上这个标签罢了。</p><p>在Instagram的互动率和粉丝增长方面，我能干翻每一个拥有六块腹肌的家伙，这是有原因的。</p><p>高影响力数字写作。</p><p>不是技术或学术写作。</p><p>我不是来教你怎么写研究论文的。我是来教你如何用能让你过上想要的生活的方式去写作。</p><p>如果你想成为内容大师（并利用无代码工具来分发你的写作并吸引受众），很明显，写作需要成为你一人企业的基础。</p><h3 id="启动一人写作企业的6个步骤" tabindex="-1">启动一人写作企业的6个步骤 <a class="header-anchor" href="#启动一人写作企业的6个步骤" aria-label="Permalink to &quot;启动一人写作企业的6个步骤&quot;">​</a></h3><blockquote><p>内容是个人与集体思想的延伸。我们输出自己的想法、信念和观点，从而形成了一个数字化的社会、文化和世界。互联网上的内容，就是集体潜意识中的内容。</p><p>《专注的艺术》（The Art Of Focus）</p></blockquote><p>我自称作家，因为这就是我每天在做的事（即使在社交媒体上看起来不像）。</p><p>通过写推文、时事通讯和长推（这些内容后来被重新利用制作成Instagram帖子、YouTube视频、LinkedIn帖子等等），我维持着每月10万到25万美元的收入（偶尔还会飙升到50万到70万美元）。这仅仅是我个人品牌的收入，不包括我的另一家公司。</p><p>回想起来，再结合这封信开头的说法，写作是一个力量倍增器，它让我每年交的税是我以前网页设计工资的20倍。这可是个不错的烦恼。</p><p>但是，如果你把一切剥离，只剩下X（推特）和一个时事通讯，我依然能维持其中的大部分收入。</p><p>不要掉入这样的陷阱：认为你必须在所有平台上都拥有疯狂的粉丝数才能替代你现在的收入。如果你不知道从哪里开始，<a href="/letters/the-7-digital-career-paths-from-zero-experience-to-advanced">遵循这个收入来源的进阶路线</a>（上周的信）。</p><p>言归正传，以下是启动你写作生意的6个步骤。</p><p><strong>1) 选择一个你聊起来就停不下来的话题</strong></p><p>暂时不要想太多。选个话题，开始练习写作。</p><p>可以是生产力、创造力、灵性、健身，或者是任何你能与之进行交谈的兴趣爱好。</p><p>如果你已经开始写作了，从<a href="/letters/dont-get-replaced-by-ai-how-to-write-authentic-content">你的话题树</a>里挑一个话题。</p><p><strong>2) 头脑风暴你的独特视角</strong></p><p>忘掉你所知道的关于“价值”的一切。</p><p>具有可操作性的建议和陈词滥调，已经不像互联网刚萌芽时那么好卖了。</p><p>新奇才能抓住眼球。如果你想让人读你写的东西，获得注意力是必须的前提。</p><p>新颖的视角是不用下三滥手段就能捕获注意力的最佳（且可复制的）方式。</p><p>你如何想出一个新颖的视角？</p><p>倾泻你的大脑（Braindump）：</p><ul><li>与该话题相关的常见问题</li><li>克服这些问题的好处</li><li>与该话题相关的常见目标</li><li>实现这些目标的绊脚石</li><li>你曾有过的亲身经历</li></ul><p>现在，把所有东西拼凑在一起，然后<em>像跟朋友聊天一样把它解释出来。</em></p><p>不要试图去抄袭别人的视角或措辞方式。用你自己的声音说出来，让它<em>随着时间、努力和练习不断完善。</em></p><p><strong>3) 每周就该话题写500-1000字</strong></p><p>你需要在深度和增长之间取得平衡。</p><p>意思是，你需要长篇内容，也需要短篇内容。</p><p>我非常赞成用创办一份时事通讯作为你的长篇形式——但在开始阶段这可以先放一放。</p><p>专注于像X（推特）这样的平台。</p><p>每周写一次长推（threads）作为你的长篇内容。</p><p>每天写2-3条短帖。</p><p>然后，为了实现增长，把最多精力集中在第5步上。</p><p>我很快就会详细拆解如何写这些内容。</p><p><strong>4) 解构并简化日常帖子的想法</strong></p><p>写长篇内容会为你提供多种可以提取的想法。</p><p>不要试图直接从你的时事通讯或长推中复制粘贴——<em>要将它们重写为独立的短帖。</em></p><p>我们将在这封信中贯穿讨论这一点。</p><p><strong>5) 学习如何让你的文章被分享（至关重要）</strong></p><p>如果没人看，你写的东西就毫无意义。</p><p>这是一个巨大的新手陷阱。</p><p>他们以为只要整天写个不停，然后期盼着算法这个“救世主”能让他们一夜成名。</p><p>错。写作只占等式的20%。流量占80%。</p><p>你得通过回复、社交拓展和分享，来为你的主页和文章获取流量。</p><p>我在<a href="/letters/how-to-actually-grow-on-social-media-what-they-dont-tell-you">《如何真正在社交媒体上获得增长：他们没告诉你的事》这封信里</a>，拆解了做到这一点的每一种可能方式。</p><p><strong>6) 把你的经验变现</strong></p><p>既然你现在有了写作，有了不断增长的受众，也有了流量——剩下唯一要做的就是创造一个产品或服务来变现了。</p><p>我们在上周的信中讨论了所有可能的选项。</p><h2 id="关于高影响力写作-你需要知道的一切" tabindex="-1">关于高影响力写作，你需要知道的一切 <a class="header-anchor" href="#关于高影响力写作-你需要知道的一切" aria-label="Permalink to &quot;关于高影响力写作，你需要知道的一切&quot;">​</a></h2><blockquote><p>写作是清晰表达思想与沟通的载体。它是一种媒介，将你的信息呈现给那些能够采纳其所展示的视角，并在该共享现实中运作的人面前。</p><p>《专注的艺术》</p></blockquote><p>市面上有很多写作框架。</p><p>在尝试了所有框架并建立它们之间的联系之后——我创建了我自己认为最有效的一套。</p><p>如果你想阅读一些可靠的写作框架，并自己把线索串联起来，以下是我最喜欢的一些：</p><p><a href="https://goinswriter.com/better-sales-copy/" target="_blank" rel="noreferrer">PASTOR</a> ——适用于长篇写作，非常适合具有说服力的博客文章和销售页面。</p><p><a href="https://www.siegemedia.com/creation/aida-model" target="_blank" rel="noreferrer">AIDA</a> ——一个基础框架，适用于推文、邮件订阅页等较短篇幅的写作，有时也可作为长篇内容的通用结构。</p><p><a href="https://www.copywritematters.com/paso-copywriting-formula/" target="_blank" rel="noreferrer">PAS(O)</a> ——非常适合任何类型的内容写作，无论长篇还是短篇。</p><p>所有这些都遵循一个能激发好奇心的通用讲故事结构：</p><ul><li><strong>引入或暗示一个问题</strong> —— 让人们对导致该问题的原因产生好奇（因果定律）。先暗示结果，然后再深入探讨原因。</li><li><strong>向人们展示潜在的事件序列</strong> —— 这很相似，但会让人们想要理解导致特定结局（故事的圆满结局）的事件序列。</li><li><strong>制造信息差</strong> —— 暗示存在特定读者渴望的具有教育意义、娱乐性或启发性的信息。</li></ul><p>好奇心一旦被激发，你必须通过以下方式兑现你的承诺：</p><ul><li>阐述或暗示某种转变的个人、客户或其他经历。一个转变前（问题）和转变后（解决办法及相关好处）的对比。</li><li>关于如何更快达成解决办法的分步建议（一个独特的解决方案）。</li><li>一个极其清晰的行动呼吁，引导他们更深入地了解你的其他内容或激发行为改变 —— 同样的，这样他们就能将那种良好的行为与你联系起来。</li></ul><p>你没必要非得使用我的框架。你可以使用任何你喜欢的。但在打造我自己的框架时，我考虑了好奇心和讲故事的这些方面。</p><p>我把我的框架称为 <strong>APAG 框架。</strong></p><p>注意力（Attention）、视角（Perspective）、优势（Advantage）和游戏化（Gamify）。</p><p>所有这些都有心理学研究的支持，目的是让某人进入类似心流的体验……让他们将那种美好的体验与你联系起来。</p><p>这能用来做什么？</p><ul><li>你的时事通讯（newsletter）</li><li>播客或 YouTube 脚本</li><li>多条推文连载（threads）或中篇帖子</li><li>销售页、落地页或订阅页</li><li>实体书或电子书的章节</li><li>课程模块、引流品（lead magnet）模块及其他教育内容</li><li>推文或短帖的潜在灵感</li><li>你用来建立业务的任何其他东西</li></ul><p>本封信的这一部分摘自 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer。</a></p><h3 id="注意力-attention-——-钩子与标题的艺术" tabindex="-1">注意力（Attention）—— 钩子与标题的艺术 <a class="header-anchor" href="#注意力-attention-——-钩子与标题的艺术" aria-label="Permalink to &quot;注意力（Attention）—— 钩子与标题的艺术&quot;">​</a></h3><p>你的钩子或标题是你内容中最重要的部分。</p><p>如果钩子抓不住他们的注意力——他们还会去读你倾注大量心血的剩余内容吗？还是会直接划过去，让你的一番苦心无人问津？</p><p>以下 3 点能让他们继续读下去：</p><ul><li><strong>相关性（Relevance）</strong> —— 它与他们的日常生活有多大关联？解决了什么痛点，或者有什么潜在好处。读者能从中得到什么？</li><li><strong>认知度（Awareness）</strong> —— 对于你所瞄准的认知水平来说，它足够简单还是足够复杂？他们能理解你接下来要展示的内容吗？</li><li><strong>付出（Effort）</strong> —— 他们多快能获得结果（教育、娱乐或启发），容易获得吗？</li></ul><p>这些不一定非得全部包含在你的标题或钩子里——但都应该纳入考量。要使用最具杀伤力的那些。</p><p>在时事通讯或文章标题中，你的发挥空间要比推文连载或其他中篇帖子（比如领英帖子）里的钩子小得多。</p><p>现在，我们可以开始用大纲和文章的各个部分（问题、好处、经历等）来拼凑我们的标题或钩子了。</p><ul><li><strong>大问题</strong> —— 你可以通过总结你列出的所有问题来创造它。</li><li><strong>大好处</strong> —— 同样，你可以通过将所有好处总结为一点来创造它。</li><li><strong>大理念</strong> —— 你能把帖子中最具冲击力的部分用一句话总结出来吗？</li><li><strong>转变过程</strong> —— 你可以使用数字或独特的名字来暗示能让他们获得结果的过程（制造信息差）。</li><li><strong>时间范围</strong> —— 你能量化一个时间范围，说明他们阅读内容或获得你承诺的结果需要多长时间吗？使用数字。</li><li><strong>负面个人经历</strong> —— 如果你在内容中加入了个人经历，你能暗示这段经历中的低谷以及相关的情绪吗？</li></ul><p>把所有这些都当作为完美钩子添砖加瓦的积木。</p><p>你没必要把它们全塞进去，特别是在标题里。</p><p>但是钩子（你内容开头的几句话）可以谈论这些，以便在读者点击阅读后抓住他们的注意力。</p><p>下面是一条带有简短钩子的推文示例，你能看出来它是如何在一句话中暗示出问题、好处和转变的吗？</p><blockquote><p>没有痴迷，你注定一事无成。\\</p><p>但没人一开始就痴迷。他们一开始只是好奇。他们去尝试。他们去创造。他们搞砸事情，他们遭遇失败。而最终，他们变得无法自拔。\\</p><p>随着时间的推移和不断的坚持，好奇心就会变成痴迷。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1728068209075519958?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">November 24, 2023</a></p></blockquote><p><strong>注意：</strong></p><p>APAG 框架的“注意力”部分可以用于长篇或短篇内容的钩子或标题。</p><p>意思是，它可以用作轮播图的第一页、推文的第一行、推文连载的钩子等。</p><p>下面所有的其他部分都将被视为长篇内容的各个章节，或者它们也可以单独用于像推文这样的短帖。</p><p>长篇内容应该遵循 APAG。</p><p>短篇内容应该是 A+P、A+A 或 A+G。</p><p>如果你能把它们全塞进一篇短帖里，那就更好了，试试看。</p><h3 id="视角-perspective-——-描绘敌人的画面-或为什么某种视角是错的" tabindex="-1">视角（Perspective）—— 描绘敌人的画面，或为什么某种视角是错的 <a class="header-anchor" href="#视角-perspective-——-描绘敌人的画面-或为什么某种视角是错的" aria-label="Permalink to &quot;视角（Perspective）—— 描绘敌人的画面，或为什么某种视角是错的&quot;">​</a></h3><p>在这里，你要与读者当前正在经历的问题产生共鸣，并将其放大。这里也是你塑造故事“敌人”的地方。</p><p>做到这一点的最佳方法，就是描绘一幅关于你正在写作的话题的常见视角的画面。</p><p><em>着重强调与该视角相关的问题，以及它们所造成的痛苦。</em></p><p><em>这可以直接说明，也可以暗示。以下是一条推文示例，它描绘了一个视角，但没有直接陈述问题：</em></p><blockquote><p>醒来。<br> 按 4 次贪睡键。<br> 盯着手机看。<br> 滚下床。<br> 泡咖啡。<br> 堵在路上。<br> 8 小时毫无成就感的工作。<br> 堵在路上……又一次。<br> 跟你的“另一半”吵架。<br> 遛宠物。<br> 看电视。<br> 昏睡过去。<br> 重复。\\</p><p>这应该把你吓得魂飞魄散才对。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1628758834192736256?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">February 23, 2023</a></p></blockquote><p>为了增强火力，可以用你对那个视角的亲身经历来与他们产生共鸣。</p><p>这就是我开启大多数文章、时事通讯、视频和推文连载的方式。我会分享一段个人经历，以此来帮助说明问题并与读者产生共鸣。</p><p>人们渴望感到被理解。如果他们觉得自己被理解了，就会更乐意听你接下来的话。</p><p><strong>不知道这部分该说些什么？</strong></p><p>好的写作就是把你手头可用的一切拼凑起来。</p><p>对于“视角”，你可以使用：</p><ul><li>问题</li><li>好处</li><li>例子</li><li>比喻</li><li>引用或推文</li><li>个人故事或流行故事</li><li>比较</li><li>概念</li></ul><p><em>这些元素（我们在 Kortex 中这么称呼它们）中的任何一个，都可以用来作为一个章节的开头、过渡或结尾。</em></p><p>如果你遇到写作瓶颈，去研究或思考一下问题、例子、推文、比较等。</p><h3 id="优势-advantage-——-描绘英雄的画面、愿景-或为什么你的视角是对的" tabindex="-1">优势（Advantage）—— 描绘英雄的画面、愿景，或为什么你的视角是对的 <a class="header-anchor" href="#优势-advantage-——-描绘英雄的画面、愿景-或为什么你的视角是对的" aria-label="Permalink to &quot;优势（Advantage）—— 描绘英雄的画面、愿景，或为什么你的视角是对的&quot;">​</a></h3><p>请注意，APAG 框架的任何部分既可以是一句话，也可以是整整一节的内容。</p><p>只要你触及了每个部分就没问题。如果你想不出还能写什么，直接进入下一部分即可。</p><p>在有说服力的写作中，你是在提出一个可信的论点来推销某种东西。</p><p>你无时无刻不在推销，或者至少你应该这样做。</p><p>不仅仅是推销产品 —— 而是推销理念和更好的做事方式。这才是人们想要的。通过推销，把人们从低意识的生存状态中解救出来。</p><p>既然你已经描绘了他们错误的视角以及随之而来的问题 —— 现在你可以开始转变他们的视角，让他们用你的方式来看待事物了。</p><ul><li>你该如何教育人们，直到他们理解你的视角？</li><li>为了理解你现在的立场，他们需要知道些什么？</li><li>你的文章中缺失了什么，以至于阻碍了他们理解你更好的做事方式？</li></ul><p>在这里，你可以呈现新颖的想法、概念、社会认同以及能让你的论点令人信服的经历。</p><p>如果你有可以引用的名言、推文或其他参考资料，加进去吧 —— 这只会让你的论点更加可信。</p><p>下面是我写的一条关于“优势”的推文示例：</p><blockquote><p>写作是一项极好的技能，因为它能与任何其他技能或兴趣相结合。\\</p><p>如果你会写作，你就可以做任何你想做的事，并把你从这些追求中发现的价值传播出去。\\</p><p>写作让你能靠生活本身谋生。问题在于大多数人并不</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1656228093453914112?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">May 10, 2023</a></p></blockquote><p>这是这个隐喻故事的转折点。你正在向他们展示一种更好的做事方式。</p><p>同样的，你可以运用例子、问题、好处、故事、比喻、引用、推文等来帮助构建你的论点，让它更具说服力。</p><h3 id="游戏化-gamify-——-建立具有挑战性的目标层级" tabindex="-1">游戏化（Gamify）—— 建立具有挑战性的目标层级 <a class="header-anchor" href="#游戏化-gamify-——-建立具有挑战性的目标层级" aria-label="Permalink to &quot;游戏化（Gamify）—— 建立具有挑战性的目标层级&quot;">​</a></h3><p>提到游戏，你就会想到一套设定好的目标层级（或是探索任务、使命等），它们能让人清楚地知道该做什么。</p><p>如果做得好，当你给人们提供与他们技能相匹配的挑战时，你就能让读者进入一种心流状态，去发现对他们未来有帮助的新颖想法。</p><p>简而言之，你通过提供关于如何实现帖子中所述转变的分步建议来进行“游戏化”。（从问题重重的旧视角，转变为占据优势的新视角）。</p><p>你正在把所有东西打包成一种清晰、简洁且可操作的方式，以此来获得特定的结果 —— 并让他们清楚接下来该做什么。</p><p>哪些步骤（或建议）能帮助他们克服你在“视角”中提到的问题？</p><p>他们现在可以立刻执行什么来获得结果？</p><p>列出步骤、关键点，或其他有助于他们解决问题的东西，比如必读书单。</p><p>下面是我写的一条独特的“游戏化”推文示例 —— 后来它变成了一篇关于日常习惯的时事通讯，并且很容易就能转化成一篇推文连载的关键点：</p><blockquote><p>你需要 4 个习惯：\\</p><p>一个建设心智。<br> 一个强健体魄。<br> 一个建立事业。<br> 一个经营关系。\\</p><p>美好的生活，就是成为你所能成为的一切的过程。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1723689606774706247?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">November 12, 2023</a></p></blockquote><p><strong>如果你还没看懂（这很正常）</strong></p><p>你将不得不去理解并内化网上大多数长篇内容的结构。</p><p>你也得去理解如何讲故事。它们两者是互通的。</p><p>下面是常见的说服性写作结构：</p><ul><li><strong>钩子（Hook）</strong> — 我们已经讨论过这个了。</li><li><strong>导语（Lead）</strong> — 引入并激化问题</li><li><strong>正文（Body）</strong> — 关键点（编号或不编号），由小标题分隔，以帮助学习和理解主题</li><li><strong>结尾（Conclusion）</strong> — 总结，或提供克服问题的分步建议</li><li><strong>行动呼吁（CTA）</strong> — 呼吁读者接下来去采取某项行动（在短帖子中并非必需）</li></ul><p>这<strong>就是</strong>一个讲故事的结构。</p><p>讲故事<strong>并不</strong>总是单纯讲一个故事。</p><p>故事可以由轶事、研究、案例、隐喻、金句引用、推文、视频、其他内容，以及任何你能用来帮助他人理解的东西组成。</p><p>这就是为什么拥有一个装满你所收集的各种想法的第二大脑（比如 <a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a>）如此重要。随着它的充实，写作会变得异常简单。你只需要以无数种方式把这些想法拼凑起来。</p><p>你抛出一个问题，并引导他人去克服它。</p><h2 id="短内容写作的关键" tabindex="-1">短内容写作的关键 <a class="header-anchor" href="#短内容写作的关键" aria-label="Permalink to &quot;短内容写作的关键&quot;">​</a></h2><p>上述所有方法都可以用来撰写短帖子，比如推文、IG帖子、LinkedIn帖子、Reels短视频脚本等等。</p><p>但是，你怎么才能把它们写得更好呢？</p><p>模仿。</p><p>我是通过观察学会写出好推文的。</p><p>既然你的其他写作中已经涌现出了想法，那就把这些想法拿出来，然后：</p><ul><li>研究你最喜欢的作者的语录</li><li>使用像 Twemex 这样的工具来研究高赞帖子 (链接)</li><li>做一个研究者而不是消费者——阅读社交媒体内容来研究别人的帖子结构</li><li>对于你看到的每一篇帖子，试着用你自己的想法去重构它，以此训练你的大脑像那样去写作</li></ul><p><em>让自己沉浸在优秀的短内容写作中。</em></p><p><em>把他们的句子结构当作辅助轮，来写出你自己的内容。</em></p><p><em>思考为什么那篇作品能火。它让你感觉如何？为什么它会让你产生那种感觉？</em></p><p>我在这里写过一整封长信，探讨 <a href="/letters/dont-get-replaced-by-ai-how-to-write-authentic-content">如何创作短内容</a>。</p><p>你也可以在 <a href="https://www.dropbox.com/scl/fi/nhvzkqzbzlp6ro6ocb8a4/ContentPresentation.pdf?rlkey=8kpb8t3wgc21wu9acqg33c80v&amp;dl=0" target="_blank" rel="noreferrer">这份 PDF 中</a> 下载我的一些最佳推文，将它们作为你创作内容的辅助轮。</p><p>所有这些都需要练习，大量的练习。</p><p>但如果你想通过自己拥有的任何其他技能来赚取收入，你必须将它与写作这项技能结合起来。</p><p>感谢阅读，希望这对你有所帮助。</p><p>Dan</p><hr><p><a href="/en/letters/learn-this-skill-if-you-want-to-survive-the-next-10-years">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',201))])}const A=l(h,[["render",c]]);export{_ as __pageData,A as default};
